// The per-locale data of the Intl services (generated by tools/intl/gen-locale-data.mjs into locale_data.inc).
#include <algorithm>

#include "builtins/intl/intl.h"

namespace snowman::intl::data {

namespace {

struct AliasEntry {
  const char* from;
  const char* to;
};
#include "builtins/intl/locale_data.inc"

// The value for `locale` in an inheritance table, or rootValue.
template <size_t N>
std::string inherited(const AliasEntry (&table)[N], std::string_view locale, const char* rootValue) {
  std::string candidate(locale);
  while (!candidate.empty()) {
    const AliasEntry* end = table + N;
    const AliasEntry* it = std::lower_bound(table, end, candidate,
                                            [](const AliasEntry& e, const std::string& k) { return std::string_view(e.from) < k; });
    if (it != end && candidate == it->from) return it->to;
    candidate = parentLocale(candidate);
  }
  return rootValue;
}

}  // namespace

std::span<const std::string> locales() {
  static const std::vector<std::string> list(std::begin(kLocales), std::end(kLocales));
  return list;
}

std::string parentLocale(std::string_view locale) {
  size_t pos = locale.rfind('-');
  if (pos == std::string_view::npos) return {};
  if (pos >= 2 && locale[pos - 2] == '-') pos -= 2;
  return std::string(locale.substr(0, pos));
}

std::string defaultNumberingSystem(std::string_view locale) { return inherited(kDefaultNumberingSystems, locale, "latn"); }
std::string defaultCalendar(std::string_view locale) { return inherited(kDefaultCalendars, locale, "gregory"); }
std::string defaultHourCycle(std::string_view locale) { return inherited(kDefaultHourCycles, locale, "h23"); }
std::vector<std::string> collations(std::string_view locale) { return split(inherited(kCollations, locale, "emoji eor"), ' '); }

const char16_t* numberingSystemDigits(std::string_view numberingSystem) {
  for (const DigitsEntry& e : kNumberingSystemDigits)
    if (numberingSystem == e.name) return e.digits;
  return nullptr;
}

std::vector<std::string> numberingSystems() {
  std::vector<std::string> out;
  for (const DigitsEntry& e : kNumberingSystemDigits) out.emplace_back(e.name);
  std::sort(out.begin(), out.end());
  return out;
}

bool isSupportedNumberingSystem(std::string_view numberingSystem) { return numberingSystemDigits(numberingSystem) != nullptr; }

std::vector<std::string> calendars() { return {std::begin(kCalendars), std::end(kCalendars)}; }
std::vector<std::string> collationTypes() { return {std::begin(kCollationTypes), std::end(kCollationTypes)}; }
std::vector<std::string> currencies() { return {std::begin(kCurrencies), std::end(kCurrencies)}; }
std::vector<std::string> units() { return {std::begin(kUnits), std::end(kUnits)}; }
bool isSanctionedSimpleUnit(std::string_view unit) {
  return std::binary_search(std::begin(kUnits), std::end(kUnits), unit,
                            [](std::string_view a, std::string_view b) { return a < b; });
}

std::optional<std::string> primaryTimeZone(std::string_view name) {
  std::string key = asciiLower(name);
  const AliasEntry* end = std::end(kTimeZones);
  const AliasEntry* it = std::lower_bound(std::begin(kTimeZones), end, key,
                                          [](const AliasEntry& e, const std::string& k) { return std::string_view(e.from) < k; });
  if (it != end && key == it->from) return std::string(it->to);
  return std::nullopt;
}

std::vector<std::string> primaryTimeZones() {
  std::vector<std::string> out;
  for (const AliasEntry& e : kTimeZones) out.emplace_back(e.to);
  std::sort(out.begin(), out.end());
  out.erase(std::unique(out.begin(), out.end()), out.end());
  return out;
}

std::vector<std::string> regionTimeZones(std::string_view region) {
  std::vector<std::string> out;
  for (const AliasEntry& e : kTimeZoneRegions)
    if (region == e.from) out.emplace_back(e.to);
  return out;
}

namespace {

template <size_t N>
const char* byRegion(const AliasEntry (&table)[N], std::string_view region) {
  for (std::string_view r : {region, std::string_view("001")}) {
    const AliasEntry* end = table + N;
    const AliasEntry* it = std::lower_bound(table, end, r, [](const AliasEntry& e, std::string_view k) { return std::string_view(e.from) < k; });
    if (it != end && r == it->from) return it->to;
  }
  return "";
}

}  // namespace

std::vector<std::string> regionCalendars(std::string_view region) { return split(byRegion(kRegionCalendars, region), ' '); }
std::vector<std::string> regionHourCycles(std::string_view region) { return split(byRegion(kRegionHourCycles, region), ' '); }
WeekData regionWeek(std::string_view region) {
  std::string_view w = byRegion(kRegionWeeks, region);
  return {w[0] - '0', w[1] - '0', w[2] - '0', w[3] - '0'};
}
bool isRtlScript(std::string_view script) {
  for (const char* s : kRtlScripts)
    if (script == s) return true;
  return false;
}

}  // namespace snowman::intl::data
